    "P": "<svg viewBox=\"0 0 100 120\" class=\"asl-hand-svg\" fill=\"none\" stroke=\"#06b6d4\" stroke-width=\"2.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n  <!-- Pronated Forearm entering from top -->\n  <path d=\"M 32 6 C 32 18 34 28 38 38 L 62 38 C 66 28 68 18 68 6\" stroke=\"#06b6d4\" stroke-width=\"2.6\" />\n  <path d=\"M 32 6 C 42 8 58 8 68 6\" stroke=\"#06b6d4\" stroke-width=\"1.8\" opacity=\"0.6\" />\n  <!-- Curled Ring & Pinky Fingers tucked at top right -->\n  <path d=\"M 58 38 C 64 36 72 40 72 48 C 72 56 64 58 58 54 Z\" fill=\"#06b6d422\" stroke=\"#06b6d4\" stroke-width=\"2.6\" />\n  <!-- Index finger pointing straight down -->\n  <path d=\"M 38 38 L 38 96 C 38 102 49.0 102 49.0 96 L 49.0 38 Z\" fill=\"#06b6d422\" stroke=\"#06b6d4\" stroke-width=\"2.6\" />\n  <ellipse cx=\"43.5\" cy=\"92\" rx=\"4.5\" ry=\"2.5\" stroke=\"#06b6d4\" stroke-width=\"1.2\" />\n  <!-- Middle finger tilted downward-right -->\n  <path d=\"M 46 44 L 66 84 C 70 90 80 84 76 78 L 56 38 Z\" fill=\"#06b6d422\" stroke=\"#06b6d4\" stroke-width=\"2.6\" />\n  <!-- Thumb nestled between index and middle, resting against middle knuckle -->\n  <path d=\"M 36 44 C 42 46 50 48 54 56 C 54 64 44 66 38 58 Z\" fill=\"var(--card-bg)\" stroke=\"#06b6d4\" stroke-width=\"2.6\" />\n  <ellipse cx=\"48\" cy=\"54\" rx=\"3.5\" ry=\"3.5\" stroke=\"#06b6d4\" stroke-width=\"1.3\" />\n</svg>",
