    "E": "<svg viewBox=\"0 0 100 120\" class=\"asl-hand-svg\" fill=\"none\" stroke=\"#06b6d4\" stroke-width=\"3.0\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n\n  <!-- Wrist and Lower Palm -->\n  <path d=\"M 33.0 114 C 31.0 98 30.0 86 28.0 76 C 25.0 66 25.0 56 29.0 48\" stroke=\"#06b6d4\" stroke-width=\"3.0\" />\n  <path d=\"M 67.0 114 C 68.0 98 71.0 86 74.0 74 C 77.0 62 75.0 54 72.0 48\" stroke=\"#06b6d4\" stroke-width=\"3.0\" />\n  <path d=\"M 33.0 114 C 42 116 58 116 67.0 114\" stroke=\"#06b6d4\" stroke-width=\"2.2\" opacity=\"0.6\" />\n\n  <!-- 4 Flexed Finger Knuckles Resting on Thumb Shelf -->\n  <path d=\"M 23.25 66 L 23.25 48 C 23.25 42 36.25 42 36.25 48 L 36.25 66\" fill=\"#06b6d422\" stroke=\"#06b6d4\" stroke-width=\"3.0\" />\n  <path d=\"M 36.75 66 L 36.75 46 C 36.75 40 49.75 40 49.75 46 L 49.75 66\" fill=\"#06b6d422\" stroke=\"#06b6d4\" stroke-width=\"3.0\" />\n  <path d=\"M 50.25 66 L 50.25 48 C 50.25 42 63.25 42 63.25 48 L 63.25 66\" fill=\"#06b6d422\" stroke=\"#06b6d4\" stroke-width=\"3.0\" />\n  <path d=\"M 63.75 66 L 63.75 50 C 63.75 44 76.75 44 76.75 50 L 76.75 66\" fill=\"#06b6d422\" stroke=\"#06b6d4\" stroke-width=\"3.0\" />\n  <!-- Knuckle flexion crease lines -->\n  <line x1=\"25.25\" y1=\"54\" x2=\"34.25\" y2=\"54\" stroke=\"#06b6d4\" stroke-width=\"1.2\" opacity=\"0.7\" />\n  <line x1=\"38.75\" y1=\"52\" x2=\"47.75\" y2=\"52\" stroke=\"#06b6d4\" stroke-width=\"1.2\" opacity=\"0.7\" />\n  <line x1=\"52.25\" y1=\"54\" x2=\"61.25\" y2=\"54\" stroke=\"#06b6d4\" stroke-width=\"1.2\" opacity=\"0.7\" />\n  <line x1=\"65.75\" y1=\"56\" x2=\"74.75\" y2=\"56\" stroke=\"#06b6d4\" stroke-width=\"1.2\" opacity=\"0.7\" />\n  <!-- MANDATORY HORIZONTAL THUMB SHELF (Closed E Bed) -->\n  <path d=\"M 22 78 C 26 67 44 65 74 66 C 82 66 82 76 74 78 C 58 82 34 84 22 78 Z\" fill=\"var(--card-bg)\" stroke=\"#06b6d4\" stroke-width=\"3.0\" />\n  <ellipse cx=\"68\" cy=\"71\" rx=\"4\" ry=\"3.5\" stroke=\"#06b6d4\" stroke-width=\"1.4\" />\n</svg>",
